css:
.d-lt2{width:100%;max-width:340px}
.d-lt2-legend{display:flex;gap:8px;margin-bottom:4px}
.d-lt2-legend button{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border:1px solid var(--line);border-radius:999px;background:var(--paper);color:var(--ink);font:inherit;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;cursor:pointer}
.d-lt2-legend button[aria-pressed="false"]{color:var(--faint);text-decoration:line-through}
.d-lt2-legend i{width:10px;height:2px;display:block;background:var(--ink)}
.d-lt2-legend button:nth-child(2) i{background:var(--ink-vermilion)}
.d-lt2-legend button:nth-child(3) i{background:var(--ink-indigo)}
.d-lt2-svg{display:block;width:100%;height:auto;overflow:visible}
.d-lt2-axis{stroke:var(--line);stroke-width:1}
.d-lt2-line{fill:none;stroke-width:1.5;stroke-linejoin:round;stroke-linecap:round;transition:opacity 180ms var(--ease-print)}
.d-lt2-s0{stroke:var(--ink)}
.d-lt2-s1{stroke:var(--ink-vermilion)}
.d-lt2-s2{stroke:var(--ink-indigo)}
.d-lt2-off{opacity:.12}

init:
root => {
  const svg = root.querySelector('.d-lt2-svg');
  const btns = [...root.querySelectorAll('[data-k]')];
  if (!svg || !btns.length) return;
  const series = [[30, 38, 35, 48, 44, 57, 62], [12, 15, 14, 19, 22, 21, 26], [4, 5, 7, 6, 9, 11, 13]];
  const W = 320, H = 170, L = 26, R = 8, T = 14, B = 26;
  const n = series[0].length, max = 70;
  const x = i => L + i * (W - L - R) / (n - 1);
  const y = v => T + (H - T - B) * (1 - v / max);
  const NS = 'http://www.w3.org/2000/svg';
  const mk = (tag, attrs) => { const el = document.createElementNS(NS, tag); for (const k in attrs) el.setAttribute(k, attrs[k]); return el; };
  for (let g = 0; g <= 3; g++) svg.appendChild(mk('line', { class: 'd-lt2-axis', x1: L, y1: T + (H - T - B) * g / 3, x2: W - R, y2: T + (H - T - B) * g / 3 }));
  const paths = series.map((s, si) => {
    const d = s.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1)).join(' ');
    const p = mk('path', { class: 'd-lt2-line d-lt2-s' + si, d: d });
    svg.appendChild(p);
    return p;
  });
  btns.forEach(b => {
    b.onclick = () => {
      const on = b.getAttribute('aria-pressed') === 'true';
      b.setAttribute('aria-pressed', on ? 'false' : 'true');
      paths[Number(b.dataset.k)].classList.toggle('d-lt2-off', on);
    };
  });
}
